from pathlib import Path
import json
import html
import pymupdf as fitz
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'output/report_changes'
old=json.loads((ROOT/'archive/before_story_revision/current_figure_manifest.json').read_text())
current=json.loads((ROOT/'data/current_figure_manifest.json').read_text())
mapping={f['previous_review_figure']:f['figure'] for f in current if f.get('previous_review_figure')}
pages=len(fitz.open(ROOT/'output/pdf/DAS732_A2_Report_IEEE.pdf'))
reasons={2:'Interactive screenshot overlaps the three-layout overview; working network page retained.',11:'Eight-date atlas omitted; all three required eight-frame GIFs retained.',22:'Positive-rain conditional distributions provide limited separation; original retained here.',23:'Replaced by full-domain monthly wind roses. Spatial support and near-calm handling differ.',24:'Moved from PDF appendix to companion gallery: exact adjacency lookup remains available.',26:'Bubble overview retained here; PCP and SPLOM provide more precise comparisons.',31:'Moved from PDF appendix to companion gallery: worked horizon construction remains available.',32:'Moved from PDF appendix to companion gallery: KDE sensitivity remains available.'}
md=['# Current report changes',f'The preceding compact report had 25 pages and 29 figures. The current report has **{pages} pages and 30 figures**, within the 27-page maximum. No original graph was deleted.','## Restored and replaced','- Restored original Figure 18, monthly temperature maps, as current Figure 20. Absolute monthly levels complement the difference maps.\n- Restored original Figure 25, regional adoption dumbbells, as current Figure 12. Their endpoint panel is now combined with a raincloud of matched individual gains.\n- Replaced the PDF adoption alluvial with Figure 10, adoption quantiles and paired gains. It directly tests absolute convergence and distinguishes differences of quantiles from quantiles of changes. The alluvial remains in the companion gallery.\n- Moved adjacency, horizon construction and KDE sensitivity from the PDF appendix to the companion gallery. Required method experiments remain in the PDF. Added Figure 11 compares absolute and relative inequality over all years. Figure 23 upgrades the original monthly rainfall maps with five-day concentration.','## Layout and explanations','Normal font sizes are retained. The daily quantile-ribbon height cap is adjusted slightly to avoid an overfull two-figure page; remaining image-size limits are retained. Each PDF figure keeps its question, encoding, detailed interpretation, limitations and takeaway. Repeated rationale and measured-findings paragraphs are omitted from the PDF; all six reading-guide fields remain in REPORT.md and the gallery. References and contribution/disclosure text are included within the page count.','## Full original-to-current mapping','| Original 32-figure ID | Graph | Current treatment |\n|---|---|---|']
cards=[];rows=[]
md[1]=f'The report now has **{pages} pages, 30 figure sets and nine references**. The previous version is preserved in archive/before_simple_revision_20261024.zip.'
md[3]='- Figure 1 explains line membership versus layout distance.\n- Figure 3 adds a NodeTrix overview and a labelled group-7 matrix.\n- Figures 4–5 show six named country paths; Figure 6 uses two larger scatterplots.\n- Figure 7 replaces the crowded regional scatterplots with a bar comparison.\n- Figure 11 replaces the A1-like absolute/relative comparison with within-region country variation.\n- Figure 29 replaces UpSet with four simple bars.\n- The setup is reduced to one page; Table 1 and the temporary AI paragraph are removed. Notes are short and the English is simpler.\n- Fixed figure blocks keep each image with its explanation. The 17-slide deck and recording guide use the same revised story.'
md[5]='The report uses short reading guides, results and essential notes. Required method variants remain. Earlier plots are retained in the companion gallery. The team will add its final AI disclosure. Nine key data/method references remain.'
for f in old:
    n=f['figure'];status=(f'Figure {mapping[n]}' + (' (upgraded composite)' if n in [19,25] else '')) if n in mapping else reasons[n]
    md.append(f'| {n} | {f["title"]} | {status} |')
    if n not in mapping:
        rows.append(dict(previous_figure=n,title=f['title'],path=f['path'],status=status,reason=status))
        cards.append('<section><h2>Original Figure '+str(n)+'. '+html.escape(f['title'])+'</h2><p>'+html.escape(status)+'</p><img src="../../'+f['path']+'"></section>')
(ROOT/'REPORT_CHANGE_REVIEW.md').write_text('\n\n'.join(md[:7])+'\n\n'+'\n'.join(md[7:]),encoding='utf-8')
(OUT/'changes.json').write_text(json.dumps(rows,indent=2))
(OUT/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>Current report changes</title><style>body{font:17px/1.6 system-ui;max-width:1100px;margin:40px auto;padding:0 24px;color:#193044}img{max-width:100%}section{border-top:1px solid #ccc;margin-top:30px}</style><h1>Report changes: '+str(pages)+' pages, 30 figures</h1><p>Simple-English revision: NodeTrix detail (Figure 3), six-country paths (Figures 4–5), regional change counts (Figure 7), within-region variation (Figure 11) and weather overlap bars (Figure 29). Supporting checks and other trials remain in companion galleries.</p><p><a href="../../REPORT_CHANGE_REVIEW.md">Full changes and mapping</a> | <a href="../quality_figures/index.html">Current figures and companion material</a> | <a href="../pdf/DAS732_A2_Report_IEEE.pdf">Current PDF</a> | <a href="../../archive/before_story_revision/DAS732_A2_Report_IEEE.pdf">Original report</a></p>'+''.join(cards)+'</html>',encoding='utf-8')
print('Updated comparison gallery and complete original-to-current map.')
